public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k <= 0) {
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // handle negative numbers
        count[rem]++;
    }
    // Remainder 0 must be even
    if (count[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 must also be even
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) {
            return false;
        }
    }
    // For other remainders, counts must match complementary remainders
    for (int r = 1; r <= k / 2; r++) {
        if (k % 2 == 0 && r == k / 2) {
            continue; // already handled
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(0);
    java.util.ArrayList<Integer> order = new java.util.ArrayList<>();
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order.add(node);
        for (int nei : graph[node]) {
            if (nei != parent[node]) {
                parent[nei] = node;
                stack.push(nei);
            }
        }
    }
    int[] hasAppleSub = new int[n];
    int total = 0;
    for (int i = order.size() - 1; i >= 0; i--) {
        int node = order.get(i);
        int has = hasApple[node] ? 1 : 0;
        for (int nei : graph[node]) {
            if (nei != parent[node]) {
                if (hasAppleSub[nei] == 1) {
                    has = 1;
                    total += 2;
                }
            }
        }
        hasAppleSub[node] = has;
    }
    return total;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        if (c >= 'a' && c <= 'z') {
            freq[c - 'a']++;
        } else {
            // If characters outside 'a'-'z' are present, treat them separately
            // by expanding the frequency array or handling them directly.
            // For simplicity, we ignore them in this implementation.
        }
    }
    StringBuilder result = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass: pick smallest available characters
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        // Descending pass: pick largest available characters
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // Try all possible subset sizes k from 1 to n/2
    for (int k = 1; k <= n / 2; k++) {
        // The target sum for subset of size k must be integer
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
        // dp[i] holds all possible sums using i elements
        @SuppressWarnings("unchecked")
        java.util.HashSet<Integer>[] dp = new java.util.HashSet[k + 1];
        for (int i = 0; i <= k; i++) {
            dp[i] = new java.util.HashSet<>();
        }
        dp[0].add(0);
        for (int num : nums) {
            // iterate backwards to avoid using the same element multiple times
            for (int i = Math.min(k, n); i >= 1; i--) {
                if (dp[i - 1].isEmpty()) {
                    continue;
                }
                for (int prevSum : dp[i - 1]) {
                    int newSum = prevSum + num;
                    if (newSum <= target) { // pruning: sums larger than target are useless
                        dp[i].add(newSum);
                    }
                }
            }
        }
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start at step 1 (top) with no cost
        return 0;
    }
    // dp[i] = minimum cost to reach step i
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int costPrev = cost[i - 1];
        dp[i] = costPrev + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n], dp[n - 1]);
}

