public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    // For k > 20, 2^k would be > 1,048,576 which is impractical for this problem.
    if (k > 20) {
        return false;
    }
    int total = 1 << k;          // total number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;        // mask to keep only k bits
    int code = 0;
    int count = 0;
    for (int i = 0; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[code]) {
                seen[code] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }
    return false;
}

