public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxSum = Integer.MIN_VALUE;
    int currentMax = 0;
    int minSum = Integer.MAX_VALUE;
    int currentMin = 0;
    for (int num : nums) {
        currentMax = Math.max(num, currentMax + num);
        maxSum = Math.max(maxSum, currentMax);
        currentMin = Math.min(num, currentMin + num);
        minSum = Math.min(minSum, currentMin);
    }
    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }
    // Generate Fibonacci numbers up to k
    int[] fibs = new int[50]; // 50 is enough for int range
    fibs[0] = 1;
    fibs[1] = 1;
    int size = 2;
    while (true) {
        int next = fibs[size - 1] + fibs[size - 2];
        if (next > k) {
            break;
        }
        fibs[size++] = next;
    }
    // Greedy subtraction to find minimal count
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        if (fibs[i] <= remaining) {
            remaining -= fibs[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            // Check if current and top are the same letter in opposite cases
            if (Math.abs(current - top) == 32) {
                stack.deleteCharAt(len - 1); // remove the pair
                continue;
            }
        }
        stack.append(current);
    }
    return stack.toString();
}

