private void dfs(String s, int index, java.util.Set<java.lang.String> seen, int[] max) {
    if (index == s.length()) {
        max[0] = Math.max(max[0], seen.size());
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        java.lang.String sub = s.substring(index, end);
        if (!seen.contains(sub)) {
            seen.add(sub);
            dfs(s, end, seen, max);
            seen.remove(sub);
        }
    }
}

