public String getSmallestString(int n, int k) {
    if (n <= 0 || k < n || k > 26 * n) {
        return "";
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        sb.append('a');
    }
    int remaining = k - n; // extra value needed beyond all 'a's
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // can increase up to 'z'
        sb.setCharAt(i, (char) ('a' + add));
        remaining -= add;
    }
    return sb.toString();
}

