public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    int[] stack = new int[n + 1];
    int top = -1;
    for (int i = 0; i <= n; i++) {
        int curHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && curHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum < m + n - 1; sum++) {
        int start = Math.max(0, sum - n + 1);
        int end = Math.min(m - 1, sum);
        if (sum % 2 == 0) {
            for (int i = end; i >= start; i--) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        } else {
            for (int i = start; i <= end; i++) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    int left = i + 1;
    int right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    long result = Long.parseLong(new String(digits));
    if (result > Integer.MAX_VALUE) {
        return -1;
    }
    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    return build(n, n);
}

private static List<String> build(int currentLen, int totalLen) {
    if (currentLen == 0) {
        return new ArrayList<>(Arrays.asList(""));
    }
    if (currentLen == 1) {
        return new ArrayList<>(Arrays.asList("0", "1", "8"));
    }
    List<String> prev = build(currentLen - 2, totalLen);
    List<String> result = new ArrayList<>();
    for (String s : prev) {
        if (currentLen != totalLen) {
            result.add("0" + s + "0");
        }
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    int cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    long[] ugly = new long[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    long next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        long nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return (int) ugly[n - 1];
}

